    2: {label:"EMPATE",loss:0,wound:false,note:"Ninguna parte se impone."},
    3: {label:"IMPACTO",loss:1,wound:false,note:"El Rival pierde 1 Peso."},
    4: {label:"QUIEBRE",loss:1,wound:true,note:"El Rival pierde 1 Peso y recibe una Herida; sin descontar Peso adicional."}
  })[face] ?? null;
}
