function hiperaDescansoPlan(props) {
  if (!props) return null;
  const parse=v=>v===null||v===undefined||v===""||typeof v==="boolean"?NaN:Number(v);
  const newen=parse(props.newen), aguante=parse(props.aguante), neque=parse(props.neque);
  const marks=[props.arraigo_1,props.arraigo_2,props.arraigo_3];
  const checked=v=>v===true||v===1||v==="1"||v==="true"||v==="on";
  const unchecked=v=>v===false||v===0||v==="0"||v==="false"||v==="off"||v==="";
  const arraigo=marks.every(v=>checked(v)||unchecked(v)) ? marks.filter(checked).length :
    marks.every(v=>v===undefined||v===null) ? parse(props.arraigo) : NaN;
  if (![newen,aguante,neque,arraigo].every(Number.isInteger) ||
      neque<1||neque>4||aguante<0||aguante>neque||newen<0||newen>4||arraigo<0||arraigo>3) return null;
  return {arraigo,newenBefore:newen,newenAfter:Math.min(4,newen+arraigo),aguanteBefore:aguante,aguanteAfter:neque};
}
async function hiperaRestApply(actor) {
  if (!actor?.isOwner || actorIsInActiveCombat(actor) || pendingByActor.has(actor.uuid)) return null;
  const plan=hiperaDescansoPlan(actor.system?.props);
  if (!plan || (plan.newenBefore===plan.newenAfter && plan.aguanteBefore===plan.aguanteAfter)) return null;
  await actor.update({"system.props.newen":plan.newenAfter,"system.props.aguante":plan.aguanteAfter});
  return plan;
}

const HIPERA_CODE_FAMILIES=Object.freeze({
  Sabio:["Inscribir","Significar"],Cantor:["Significar","Convocar"],
  Viajero:["Señalizar","Convocar"],Explorador:["Señalizar","Convocar"],Guerrero:["Significar","Convocar"]
});
function hiperaCodeFamilies(props) {return HIPERA_CODE_FAMILIES[String(props?.oficio??"").trim()]??[];}
function hiperaCodeCap(props) {
  const n=Number(props?.picardia);return Number.isInteger(n)&&n>=1&&n<=4?n:0;
}
function hiperaCodeKey(s){return String(s??"").normalize("NFC").trim().replace(/\s+/g," ").toLocaleLowerCase("es");}
function hiperaCodeRead(raw){
  if(raw===undefined||raw===null)return [null,null,null,null];
  if(!Array.isArray(raw)||raw.length!==4)return null;
  if(!raw.every(x=>x===null||(typeof x.id==="string"&&typeof x.name==="string"&&["Inscribir","Significar","Señalizar","Convocar"].includes(x.family)&&Array.isArray(x.forms)&&x.forms.every(f=>typeof f.culture==="string"&&typeof f.name==="string"))))return null;
  return raw.map(x=>x?{...x,forms:x.forms.map(f=>({...f}))}:null);
}
function hiperaCodePlan(raw,props,index,request){
  const slots=hiperaCodeRead(raw),cap=hiperaCodeCap(props),families=hiperaCodeFamilies(props);
  const fail=error=>({ok:false,error});
  if(!slots||!Number.isInteger(index)||index<0||index>=4||!cap||!families.length)return fail("Datos de Códigos, Oficio o Picardía no válidos.");
  const current=slots[index],used=slots.filter(Boolean).length,mode=request?.mode;
  if(!["add","form","replace"].includes(mode)||!request.confirmed)return fail("Falta confirmar aprendizaje efectivo y validación de la Voz del Mundo.");
  const culture=String(request.culture??"").trim(),form=String(request.form??"").trim();
  if(!culture||!form||culture.length>80||form.length>120)return fail("Indica Cultura y forma concreta aprendida.");
  if(mode==="form"){
    if(!current)return fail("No hay práctica registrada.");
    if(!families.includes(current.family))return fail("La familia de esta práctica no está permitida por el Oficio actual; se conserva su registro.");
    if(current.forms.some(f=>hiperaCodeKey(f.culture)===hiperaCodeKey(culture)&&hiperaCodeKey(f.name)===hiperaCodeKey(form)))return fail("Esa forma cultural ya está registrada.");
    current.forms.push({culture,name:form});
    return {ok:true,slots};
  }
  if(mode==="add"&&(current||used>=cap||index>=cap))return fail("No hay cupo disponible.");
  if(mode==="replace"&&(!current||!request.betweenAdventures||used>cap))return fail("Sustitución sólo entre aventuras, sin exceder Picardía.");
  const family=String(request.family??""),name=String(request.name??"").trim();
  if(!families.includes(family)||!name||name.length>80)return fail("Práctica o familia no permitida por Oficio.");
  if(slots.some(x=>x&&hiperaCodeKey(x.name)===hiperaCodeKey(name)))return fail("Práctica ya registrada; añade su forma cultural en el mismo cupo.");
  if(typeof request.id!=="string"||!request.id||slots.some(x=>x?.id===request.id))return fail("Identidad de práctica no válida.");
  slots[index]={id:request.id,family,name,forms:[{culture,name:form}]};
  return {ok:true,slots};
}
