function installHiperaCodes(canvas,actor){
  if(!canvas?.classList.contains("ha-kona-experimental-sheet"))return;
  const slots=hiperaCodeRead(actor.getFlag?.(MODULE_ID,"codigosV1")),cap=hiperaCodeCap(actor.system?.props);
  const used=slots?.filter(Boolean).length??0;
  for(let i=0;i<4;i++){
    const wrapper=canvas.querySelector(".ha-lengua-"+(i+1));
    if(!wrapper||wrapper.matches("input,textarea"))continue;
    wrapper.classList.add("ha-code-slot");
    let button=wrapper.querySelector(".ha-code-button");
    if(!button){
      button=document.createElement("button");button.type="button";button.className="ha-code-button";
      wrapper.appendChild(button);
      button.addEventListener("click",async event=>{
        event.preventDefault();event.stopPropagation();event.stopImmediatePropagation();
        if(button.disabled)return;
        button.disabled=true;
        try{await hiperaCodeDialog(actor,i,canvas);}catch(err){console.error("MELIAZ: Códigos",err);ui.notifications.error("MELIAZ: no se confirmó el registro de Código.");}
        finally{installHiperaCodes(canvas,actor);}
      });
    }
    const entry=slots?.[i];
    button.textContent=entry?entry.name:(i<cap&&used<cap?"+":"·");
    button.disabled=!actor.isOwner||!slots||(!entry&&(i>=cap||used>=cap));
    button.title=entry?entry.family+" · "+entry.name+" · "+entry.forms.map(f=>f.culture+": "+f.name).join(" · ")+(used>cap?" · Cupos excedidos; datos conservados":""):(button.disabled?"Cupo no disponible":"Registrar Código aprendido");
    button.setAttribute("aria-label",button.title);
  }
}

function hiperaAguanteLossPlan(props) {
  const raw=props?.aguante;
  if(raw===undefined||raw===null||raw===""||typeof raw==="boolean")return null;
  const before=Number(raw);
  if(!Number.isInteger(before)||before<0||before>4)return null;
  const after=Math.max(0,before-1);
  return {before,after,incapacitado:after===0};
}
async function hiperaOfferAguanteLoss(action,face,message) {
  if(face!==1||!action?.intercambio||!message||action.state!=="resolving"||
     action.ownerUserId!==game.user.id||!action.actor?.isOwner||action.aguanteDecision)return null;
  const actor=action.actor;
  if(message.getFlag?.(MODULE_ID,"action")?.aguanteClaimed)return null;
  const initial=hiperaAguanteLossPlan(actor.system?.props);
  if(!initial)return null;
  if(initial.before===0)return {...initial,alreadyIncapacitado:true};
  action.aguanteDecision="pending";
  let yes=false;
  try{
    yes=await foundry.applications.api.DialogV2.confirm({
      window:{title:"MELIAZ · Revés: desgaste"},
      content:"<p>¿La intención impuesta por el Rival consigue desgastar al Kona?</p><p>Confirma sólo si la Voz del Mundo determina que el desgaste alcanza directamente al Kona. La Herida no añade otra pérdida; la Armadura no evita este desgaste.</p><p>Aguante: "+initial.before+" → "+initial.after+(initial.incapacitado?" · Incapacitado":"")+"</p>",
      yes:{label:"Marcar −1 Aguante"},no:{label:"Sin pérdida directa"},rejectClose:false,modal:true});
  }catch(err){console.warn("MELIAZ: desgaste cancelado",err);}
  if(!yes){action.aguanteDecision="not-applied";return null;}
  return queueKonaActorMutation(actor,async()=>{
    if(!actor.isOwner||message.getFlag?.(MODULE_ID,"action")?.aguanteClaimed){action.aguanteDecision="not-applied";return null;}
    const plan=hiperaAguanteLossPlan(actor.system?.props);
    if(!plan||plan.before!==initial.before){action.aguanteDecision="stale";ui.notifications.warn("MELIAZ: Aguante cambió durante la confirmación; revisar desgaste con Voz del Mundo.");return {unconfirmed:true};}
    try{
      await message.update({[`flags.${MODULE_ID}.action.aguanteClaimed`]:true});
      await actor.update({"system.props.aguante":plan.after});
    }catch(err){action.aguanteDecision="error";ui.notifications.error("MELIAZ: desgaste no confirmado; revisar Aguante antes de repetir.");return {unconfirmed:true};}
    action.aguanteDecision="applied";return plan;
  });
}
function hiperaAguanteResultText(result){
  if(!result)return "";
  if(result.unconfirmed)return "Desgaste no confirmado; revisar Aguante.";
  if(result.alreadyIncapacitado)return "Aguante 0 · Incapacitado.";
  return "Aguante "+result.before+" → "+result.after+(result.incapacitado?" · Incapacitado":"");
}

function hiperaPickerNameKey(s){return String(s??"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLocaleLowerCase("es").trim();}
function hiperaPickerIndexCandidates(index,kinds,query,kindOf){
  const q=hiperaPickerNameKey(query);
  return Array.from(index??[]).filter(e=>{
    if(e.type && e.type!=="equippableItem")return false;
    if(q&&!hiperaPickerNameKey(e.name).includes(q))return false;
    const kind=kindOf(e);
    return !kind || kinds.includes(kind);
  });
}


