  if (target === "equipo" && Array.from(actor.items ?? []).filter(item =>
    ["arma", "equipo", "defensa"].includes(String(item.getFlag?.(MODULE_ID, "kind") ?? "").toLowerCase()) &&
    Number(item.getFlag?.(MODULE_ID, "equipoSlot")) > 0
