      (target === "defensa" && (!isHiperaArmorOficio(actor) || getHiperaNequeLoadoutItem(actor, "armadura")))) return;

  const packs = Array.from(game.packs ?? []).filter(pack => config.documentNames.includes(pack.documentName));
  if (!packs.length) {
