// CORE chapter V v13: combat only, never reinterpret universal tests.
function hiperaIntercambioCanRoll(initiator, value, peso) {
  return Number.isFinite(value) && Number.isFinite(peso) && peso > 0 &&
    (initiator === "rival" || (initiator === "kona" && value > peso));
}
function hiperaIntercambioOutcome(face) {
  return ({
    1: {label:"REVÉS",loss:0,wound:false,note:"El Rival se impone; complicación pertinente. Desgaste y Puede Herir según medio y escena."},
    2: {label:"EMPATE",loss:0,wound:false,note:"Ninguna parte se impone."},
    3: {label:"IMPACTO",loss:1,wound:false,note:"El Rival pierde 1 Peso."},
    4: {label:"QUIEBRE",loss:1,wound:true,note:"El Rival pierde 1 Peso y recibe una Herida; sin descontar Peso adicional."}
  })[face] ?? null;
}
function hiperaIntercambioWeapon(item) {
  return item ? {id:item.id,name:String(item.name ?? ""),quiebre:String(item.system?.props?.quiebre ?? "").trim()} : null;
}
function hiperaIntercambioLine(context) {
  if (!context) return "";
  return "<p><strong>Resolver Intercambio:</strong> " + (context.initiator === "rival" ? "agresión del Rival" : "iniciativa del Kona") +
    (context.weapon ? " · " + escapeHiperaHtml(context.weapon.name) : "") + "</p>";
}
function hiperaArmorInutilizada(actor, item) {
  return Boolean(item && (item.getFlag?.(MODULE_ID,"armaduraInutilizada") || actor.getFlag?.(MODULE_ID,"armaduraAveriada")));
}
async function hiperaOfferArmor(action, face, message) {
  if (face !== 1 || !action?.intercambio || !message || action.state !== "resolving" || action.ownerUserId !== game.user.id || action.armorDecision) return null;
  const actor=action.actor;
  if (!actor?.isOwner || !isHiperaArmorOficio(actor)) return null;
  const armor=getHiperaNequeLoadoutItem(actor,"armadura");
  if (!armor || hiperaArmorInutilizada(actor,armor)) return null;
  action.armorDecision="pending";
  let yes=false;
  try {
    yes=await foundry.applications.api.DialogV2.confirm({
      window:{title:"MELIAZ · Interponer Armadura"},
      content:"<p>¿Este Revés produciría una Herida y la Armadura puede interceptar materialmente su causa?</p><p>Si confirmas, evita la Herida y queda <strong>Inutilizada</strong> hasta repararla. El desgaste de Aguante no se evita. No protege de veneno ya inoculado ni asfixia en curso.</p>",
      yes:{label:"Interponer Armadura"},no:{label:"No interponer"},rejectClose:false,modal:true});
  } catch(err) { console.warn("MELIAZ: interposición cancelada",err); }
  const current=getHiperaNequeLoadoutItem(actor,"armadura");
  if (!yes || !actor.isOwner || current?.id !== armor.id || hiperaArmorInutilizada(actor,current)) {
    action.armorDecision="not-applied"; return null;
  }
  try {
    await current.setFlag(MODULE_ID,"armaduraInutilizada",true);
  } catch(err) {
    action.armorDecision="error";
    ui.notifications.error("MELIAZ: no se confirmó la inutilización. No dar la Herida por evitada.");
    return null;
  }
  action.armorDecision="applied";
  return {itemId:current.id,name:String(current.name ?? "Armadura"),woundPrevented:true};
}

function hiperaDescansoPlan(props) {
  if (!props) return null;
  const parse=v=>v===null||v===undefined||v===""||typeof v==="boolean"?NaN:Number(v);
  const newen=parse(props.newen), aguante=parse(props.aguante), neque=parse(props.neque);
  const marks=[props.arraigo_1,props.arraigo_2,props.arraigo_3];
  const checked=v=>v===true||v===1||v==="1"||v==="true"||v==="on";
  const unchecked=v=>v===false||v===0||v==="0"||v==="false"||v==="off"||v==="";
  const arraigo=marks.every(v=>checked(v)||unchecked(v)) ? marks.filter(checked).length :
    marks.every(v=>v===undefined||v===null) ? parse(props.arraigo) : NaN;
  if (![newen,aguante,neque,arraigo].every(Number.isInteger) ||
      neque<1||neque>4||aguante<0||aguante>neque||newen<0||newen>4||arraigo<0||arraigo>3) return null;
  return {arraigo,newenBefore:newen,newenAfter:Math.min(4,newen+arraigo),aguanteBefore:aguante,aguanteAfter:neque};
}
async function hiperaRestApply(actor) {
  if (!actor?.isOwner || actorIsInActiveCombat(actor) || pendingByActor.has(actor.uuid)) return null;
  const plan=hiperaDescansoPlan(actor.system?.props);
  if (!plan || (plan.newenBefore===plan.newenAfter && plan.aguanteBefore===plan.aguanteAfter)) return null;
  await actor.update({"system.props.newen":plan.newenAfter,"system.props.aguante":plan.aguanteAfter});
  return plan;
}

const HIPERA_CODE_FAMILIES=Object.freeze({
  Sabio:["Inscribir","Significar"],Cantor:["Significar","Convocar"],
  Viajero:["Señalizar","Convocar"],Explorador:["Señalizar","Convocar"],Guerrero:["Significar","Convocar"]
});
function hiperaCodeFamilies(props) {return HIPERA_CODE_FAMILIES[String(props?.oficio??"").trim()]??[];}
function hiperaCodeCap(props) {
  const n=Number(props?.picardia);return Number.isInteger(n)&&n>=1&&n<=4?n:0;
}
function hiperaCodeKey(s){return String(s??"").normalize("NFC").trim().replace(/\s+/g," ").toLocaleLowerCase("es");}
function hiperaCodeRead(raw){
  if(raw===undefined||raw===null)return [null,null,null,null];
  if(!Array.isArray(raw)||raw.length!==4)return null;
  if(!raw.every(x=>x===null||(typeof x.id==="string"&&typeof x.name==="string"&&["Inscribir","Significar","Señalizar","Convocar"].includes(x.family)&&Array.isArray(x.forms)&&x.forms.every(f=>typeof f.culture==="string"&&typeof f.name==="string"))))return null;
  return raw.map(x=>x?{...x,forms:x.forms.map(f=>({...f}))}:null);
}
function hiperaCodePlan(raw,props,index,request){
  const slots=hiperaCodeRead(raw),cap=hiperaCodeCap(props),families=hiperaCodeFamilies(props);
  const fail=error=>({ok:false,error});
  if(!slots||!Number.isInteger(index)||index<0||index>=4||!cap||!families.length)return fail("Datos de Códigos, Oficio o Picardía no válidos.");
  const current=slots[index],used=slots.filter(Boolean).length,mode=request?.mode;
  if(!["add","form","replace"].includes(mode)||!request.confirmed)return fail("Falta confirmar aprendizaje efectivo y validación de la Voz del Mundo.");
  const culture=String(request.culture??"").trim(),form=String(request.form??"").trim();
  if(!culture||!form||culture.length>80||form.length>120)return fail("Indica Cultura y forma concreta aprendida.");
  if(mode==="form"){
    if(!current)return fail("No hay práctica registrada.");
    if(!families.includes(current.family))return fail("La familia de esta práctica no está permitida por el Oficio actual; se conserva su registro.");
    if(current.forms.some(f=>hiperaCodeKey(f.culture)===hiperaCodeKey(culture)&&hiperaCodeKey(f.name)===hiperaCodeKey(form)))return fail("Esa forma cultural ya está registrada.");
    current.forms.push({culture,name:form});
    return {ok:true,slots};
  }
  if(mode==="add"&&(current||used>=cap||index>=cap))return fail("No hay cupo disponible.");
  if(mode==="replace"&&(!current||!request.betweenAdventures||used>cap))return fail("Sustitución sólo entre aventuras, sin exceder Picardía.");
  const family=String(request.family??""),name=String(request.name??"").trim();
  if(!families.includes(family)||!name||name.length>80)return fail("Práctica o familia no permitida por Oficio.");
  if(slots.some(x=>x&&hiperaCodeKey(x.name)===hiperaCodeKey(name)))return fail("Práctica ya registrada; añade su forma cultural en el mismo cupo.");
  if(typeof request.id!=="string"||!request.id||slots.some(x=>x?.id===request.id))return fail("Identidad de práctica no válida.");
  slots[index]={id:request.id,family,name,forms:[{culture,name:form}]};
  return {ok:true,slots};
}
async function hiperaCodeDialog(actor,index,canvas){
  if(!actor?.isOwner)return;
  const raw=actor.getFlag(MODULE_ID,"codigosV1"),slots=hiperaCodeRead(raw),props=actor.system?.props,cap=hiperaCodeCap(props);
  if(!slots||!cap){ui.notifications.warn("MELIAZ: revisar datos de Códigos.");return;}
  const current=slots[index],families=hiperaCodeFamilies(props);
  const options=families.map(f=>'<option value="'+escapeHiperaHtml(f)+'">'+escapeHiperaHtml(f)+'</option>').join("");
  const existing=current?'<p><strong>'+escapeHiperaHtml(current.name)+'</strong> · '+escapeHiperaHtml(current.family)+'</p><p>'+current.forms.map(f=>escapeHiperaHtml(f.culture)+": "+escapeHiperaHtml(f.name)).join(" · ")+'</p>':"";
  const modeOptions=current?'<option value="form">Añadir forma cultural</option><option value="replace">Sustituir práctica entre aventuras</option>':'<option value="add">Registrar práctica aprendida</option>';
  let request;
  try{
    request=await foundry.applications.api.DialogV2.prompt({
      window:{title:"MELIAZ · Códigos"},
      content:existing+'<p>Registro de aprendizaje validado en la Historia; no es un catálogo de prácticas preaprobadas.</p><label>Operación <select name="mode">'+modeOptions+'</select></label><label>Familia (nueva práctica) <select name="family">'+options+'</select></label><label>Práctica (nueva práctica) <input name="practice" maxlength="80"></label><label>Cultura <input name="culture" maxlength="80"></label><label>Forma concreta <input name="formName" maxlength="120"></label><label><input type="checkbox" name="confirmed"> Aprendizaje efectivo validado por la Voz del Mundo</label><label><input type="checkbox" name="between"> Estamos entre aventuras (para sustituir)</label>',
      ok:{label:"Registrar",callback:(event,button)=>{const e=button.form.elements;return {mode:e.mode.value,family:e.family.value,name:e.practice.value,culture:e.culture.value,form:e.formName.value,confirmed:e.confirmed.checked,betweenAdventures:e.between.checked};}},
      rejectClose:false,modal:true});
  }catch(err){console.warn("MELIAZ: Códigos cancelado",err);return;}
  if(!request)return;
  await queueKonaActorMutation(actor,async()=>{
    if(!actor.isOwner)return;
    const latest=actor.getFlag(MODULE_ID,"codigosV1");
    if(JSON.stringify(hiperaCodeRead(latest))!==JSON.stringify(slots)){ui.notifications.warn("MELIAZ: Códigos cambiaron; reabre el registro.");return;}
    const result=hiperaCodePlan(latest,actor.system?.props,index,{...request,id:foundry.utils.randomID()});
    if(!result.ok){ui.notifications.warn(result.error);return;}
    await actor.setFlag(MODULE_ID,"codigosV1",result.slots);
    installHiperaCodes(canvas,actor);
  });
}
function installHiperaCodes(canvas,actor){
  if(!canvas?.classList.contains("ha-kona-experimental-sheet"))return;
  const slots=hiperaCodeRead(actor.getFlag?.(MODULE_ID,"codigosV1")),cap=hiperaCodeCap(actor.system?.props);
  const used=slots?.filter(Boolean).length??0;
  for(let i=0;i<4;i++){
    const wrapper=canvas.querySelector(".ha-lengua-"+(i+1));
    if(!wrapper||wrapper.matches("input,textarea"))continue;
    wrapper.classList.add("ha-code-slot");
    let button=wrapper.querySelector(".ha-code-button");
    if(!button){
      button=document.createElement("button");button.type="button";button.className="ha-code-button";
      wrapper.appendChild(button);
      button.addEventListener("click",async event=>{
        event.preventDefault();event.stopPropagation();event.stopImmediatePropagation();
        if(button.disabled)return;
        button.disabled=true;
        try{await hiperaCodeDialog(actor,i,canvas);}catch(err){console.error("MELIAZ: Códigos",err);ui.notifications.error("MELIAZ: no se confirmó el registro de Código.");}
        finally{installHiperaCodes(canvas,actor);}
      });
    }
    const entry=slots?.[i];
    button.textContent=entry?entry.name:(i<cap&&used<cap?"+":"·");
    button.disabled=!actor.isOwner||!slots||(!entry&&(i>=cap||used>=cap));
    button.title=entry?entry.family+" · "+entry.name+" · "+entry.forms.map(f=>f.culture+": "+f.name).join(" · ")+(used>cap?" · Cupos excedidos; datos conservados":""):(button.disabled?"Cupo no disponible":"Registrar Código aprendido");
    button.setAttribute("aria-label",button.title);
  }
}

function hiperaAguanteLossPlan(props) {
  const raw=props?.aguante;
  if(raw===undefined||raw===null||raw===""||typeof raw==="boolean")return null;
  const before=Number(raw);
  if(!Number.isInteger(before)||before<0||before>4)return null;
  const after=Math.max(0,before-1);
  return {before,after,incapacitado:after===0};
}
async function hiperaOfferAguanteLoss(action,face,message) {
  if(face!==1||!action?.intercambio||!message||action.state!=="resolving"||
     action.ownerUserId!==game.user.id||!action.actor?.isOwner||action.aguanteDecision)return null;
  const actor=action.actor;
  if(message.getFlag?.(MODULE_ID,"action")?.aguanteClaimed)return null;
  const initial=hiperaAguanteLossPlan(actor.system?.props);
  if(!initial)return null;
  if(initial.before===0)return {...initial,alreadyIncapacitado:true};
  action.aguanteDecision="pending";
  let yes=false;
  try{
    yes=await foundry.applications.api.DialogV2.confirm({
      window:{title:"MELIAZ · Revés: desgaste"},
      content:"<p>¿La intención impuesta por el Rival consigue desgastar al Kona?</p><p>Confirma sólo si la Voz del Mundo determina que el desgaste alcanza directamente al Kona. La Herida no añade otra pérdida; la Armadura no evita este desgaste.</p><p>Aguante: "+initial.before+" → "+initial.after+(initial.incapacitado?" · Incapacitado":"")+"</p>",
      yes:{label:"Marcar −1 Aguante"},no:{label:"Sin pérdida directa"},rejectClose:false,modal:true});
  }catch(err){console.warn("MELIAZ: desgaste cancelado",err);}
  if(!yes){action.aguanteDecision="not-applied";return null;}
  return queueKonaActorMutation(actor,async()=>{
    if(!actor.isOwner||message.getFlag?.(MODULE_ID,"action")?.aguanteClaimed){action.aguanteDecision="not-applied";return null;}
    const plan=hiperaAguanteLossPlan(actor.system?.props);
    if(!plan||plan.before!==initial.before){action.aguanteDecision="stale";ui.notifications.warn("MELIAZ: Aguante cambió durante la confirmación; revisar desgaste con Voz del Mundo.");return {unconfirmed:true};}
    try{
      await message.update({[`flags.${MODULE_ID}.action.aguanteClaimed`]:true});
      await actor.update({"system.props.aguante":plan.after});
    }catch(err){action.aguanteDecision="error";ui.notifications.error("MELIAZ: desgaste no confirmado; revisar Aguante antes de repetir.");return {unconfirmed:true};}
    action.aguanteDecision="applied";return plan;
  });
}
function hiperaAguanteResultText(result){
  if(!result)return "";
  if(result.unconfirmed)return "Desgaste no confirmado; revisar Aguante.";
  if(result.alreadyIncapacitado)return "Aguante 0 · Incapacitado.";
  return "Aguante "+result.before+" → "+result.after+(result.incapacitado?" · Incapacitado":"");
}

function hiperaPickerNameKey(s){return String(s??"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLocaleLowerCase("es").trim();}
function hiperaPickerIndexCandidates(index,kinds,query,kindOf){
  const q=hiperaPickerNameKey(query);
  return Array.from(index??[]).filter(e=>{
    if(e.type && e.type!=="equippableItem")return false;
    if(q&&!hiperaPickerNameKey(e.name).includes(q))return false;
    const kind=kindOf(e);
    return !kind || kinds.includes(kind);
  });
}

